                  </div>
                  <div className="exam-section-mini">
                    <span className="section-label">Q4:</span>
                    <span>Essay - {generatedExam.second_opportunity.essay_question?.question?.substring(0, 60)}...</span>
                  </div>
                </div>
              </div>
